<script>
(()=>{'use strict';
const $=id=>document.getElementById(id), tg=window.Telegram?.WebApp, initData=tg?.initData||'', demo=new URLSearchParams(location.search).get('demo')==='1';
const state={boot:null,site:null,owner:false,pwa:!initData,connection:null,pwaConfig:null,profileDirty:false,iosPairLink:'',conversations:[],activeChat:null,deletedOnly:false,editedOnly:false,mediaOnly:false,mediaObjectUrls:[],avatarObjectUrls:[],threadBefore:0,threadHasMore:false,cropImage:null,cropUrl:'',agentFilter:'all',notificationFilter:''};
let demoQuotes=[{id:'1',text:'Делаем просто, надежно и без магии.'},{id:'2',text:'Меньше слов — больше дела.'},{id:'3',text:'Хороший код объясняет себя сам.'}];
if(tg){tg.ready();tg.expand();try{tg.setHeaderColor('#000000');tg.setBackgroundColor('#000000')}catch(e){}}
const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
function copyText(value){const text=String(value||'');if(navigator.clipboard?.writeText)return navigator.clipboard.writeText(text);const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();document.execCommand('copy');area.remove();return Promise.resolve()}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').classList.remove('show'),2600)}
function haptic(kind='light'){try{tg?.HapticFeedback?.impactOccurred(kind)}catch(e){}}
function ask(text,yes){
  if(ask.finish)ask.finish(false);
  const focus=document.activeElement, surfaces=[$('app'),$('tabs'),$('ccAgentDetail')].filter(Boolean), inert=surfaces.map(node=>node.inert);
  surfaces.forEach(node=>node.inert=true);
  $('confirmText').textContent=text;$('confirmScreen').classList.add('show');
  const onKey=event=>{
    if(event.key==='Escape'){event.preventDefault();finish(false)}
    if(event.key==='Tab'){event.preventDefault();(document.activeElement===$('confirmCancel')?$('confirmYes'):$('confirmCancel')).focus()}
  };
  const finish=value=>{
    $('confirmScreen').classList.remove('show');document.removeEventListener('keydown',onKey);
    $('confirmYes').onclick=null;$('confirmCancel').onclick=null;ask.finish=null;
    surfaces.forEach((node,index)=>node.inert=inert[index]);focus?.focus({preventScroll:true});yes(!!value);
  };
  ask.finish=finish;$('confirmYes').onclick=()=>finish(true);$('confirmCancel').onclick=()=>finish(false);
  document.addEventListener('keydown',onKey);$('confirmCancel').focus();
}
function b64bytes(value){const raw=atob(String(value||'').replace(/-/g,'+').replace(/_/g,'/')+'==='.slice((String(value||'').length+3)%4));return Uint8Array.from(raw,c=>c.charCodeAt(0))}
function bytesb64(value){const bytes=new Uint8Array(value),raw=Array.from(bytes,b=>String.fromCharCode(b)).join('');return btoa(raw).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function prepareCredentialOptions(options){const o=structuredClone(options);o.challenge=b64bytes(o.challenge);if(o.user?.id)o.user.id=b64bytes(o.user.id);for(const item of o.excludeCredentials||[])item.id=b64bytes(item.id);for(const item of o.allowCredentials||[])item.id=b64bytes(item.id);return o}
function serializeCredential(credential){const response={clientDataJSON:bytesb64(credential.response.clientDataJSON)};if(credential.response.attestationObject)response.attestationObject=bytesb64(credential.response.attestationObject);if(credential.response.authenticatorData)response.authenticatorData=bytesb64(credential.response.authenticatorData);if(credential.response.signature)response.signature=bytesb64(credential.response.signature);if(credential.response.userHandle)response.userHandle=bytesb64(credential.response.userHandle);if(credential.response.getTransports)response.transports=credential.response.getTransports();return{id:credential.id,rawId:bytesb64(credential.rawId),type:credential.type,response,clientExtensionResults:credential.getClientExtensionResults(),authenticatorAttachment:credential.authenticatorAttachment||null}}
async function passkeyAuthenticate(purpose='login',binding={}){if(!window.PublicKeyCredential)throw new Error('Это устройство не поддерживает Passkey');const start=await pwaApi('passkeys/login/options',{method:'POST',body:{purpose,binding}});if(start.status!==200||!start.data?.ok)throw new Error(start.data?.detail||'Не удалось начать проверку');const credential=await navigator.credentials.get({publicKey:prepareCredentialOptions(start.data.options)});const done=await pwaApi('passkeys/login/verify',{method:'POST',body:{transaction:start.data.transaction,credential:serializeCredential(credential)}});if(done.status!==200||!done.data?.ok)throw new Error(done.data?.detail||'Passkey отклонён');return done.data}
function workspaceFilename(value){let name=String(value||'').replace(/\\/g,'/').split('/').pop().trim();name=name.replace(/[\x00-\x1f<>:\"/\\|?*]+/g,'_').replace(/^[ .]+|[ .]+$/g,'');return(name||'xass-file.bin').slice(0,180)}
function agentActionBinding(source,command,payload={}){
 const agent=(state.boot?.sources||[]).find(item=>item.source_name===source);
 if(!agent||!Number.isSafeInteger(agent.id)||agent.id<=0)throw new Error('Обновите список устройств перед подтверждением');
 payload=JSON.parse(JSON.stringify(payload));
 if(['reboot','shutdown'].includes(command))payload.delay_sec=Number(payload.delay_sec||0);
 if(['files_list','file_download','file_delete','file_upload'].includes(command)){payload={root:String(payload.root||'').trim().toLowerCase(),path:String(payload.path||'').replace(/\\/g,'/').trim().replace(/^\/+|\/+$/g,'').split('/').filter(p=>p!==''&&p!=='.').join('/')};if(command==='file_upload')payload.filename=workspaceFilename(arguments[2]?.filename)}
 return{source_id:agent.id,command,payload};
}
async function passkeyAction(purpose,binding){
 if(!state.pwa)return'';
 if(!(state.boot?.passkeys||[]).length)throw new Error('Сначала добавьте Face ID / Passkey в разделе iPhone и веб-приложение');
 if(binding===undefined){
  binding={};
  if(purpose.startsWith('agent:')){const parts=purpose.split(':');binding=agentActionBinding(parts.slice(2).join(':'),parts[1]);}
  if(purpose.startsWith('scenario:')){const id=purpose.slice(9),item=(state.boot?.scenarios||[]).find(x=>x.id===id);if(!item)throw new Error('Обновите сценарии перед подтверждением');binding={scenario_id:id,actions:item.actions||[],devices:item.devices||[],delay_sec:item.delay_sec||0};}
 }
 const result=await passkeyAuthenticate(purpose,JSON.parse(JSON.stringify(binding)));return result.action_proof||'';
}
