async function loadAgentCommandHistory(source,row){let panel=row.querySelector('.agent-command-history-panel');if(!panel){panel=document.createElement('div');panel.className='agent-command-history-panel full';row.querySelector('.row-main').appendChild(panel)}panel.innerHTML='<div class="row-sub">Загрузка истории…</div>';try{const [commandsResponse,stateResponse]=await Promise.all([api('agents/'+encodeURIComponent(source)+'/commands'),api('agents/'+encodeURIComponent(source)+'/history')]);if(!commandsResponse.data?.ok)throw new Error(commandsResponse.data?.detail||'История недоступна');const stateRows=(stateResponse.data?.history||[]).slice(0,12),stateHtml='<div class="eyebrow" style="margin-top:12px">История состояния</div>'+stateRows.map(item=>{const m=item.metrics||{};return'<div class="log"><div class="log-meta"><span>'+(item.is_online?'ONLINE':'OFFLINE')+' · v'+esc(item.agent_version)+'</span><span>'+new Date(item.created_at).toLocaleString('ru-RU')+'</span></div><div class="log-text">CPU '+valueText(m.cpu_percent,'%')+' · RAM '+valueText(m.ram_used_percent,'%')+' · диск '+valueText(m.disk_used_percent,'%')+(item.last_error?' · '+esc(item.last_error):'')+'</div></div>'}).join(''),commandHtml='<div class="eyebrow" style="margin-top:12px">Команды</div>'+((commandsResponse.data.commands||[]).map(item=>{const message=item.result?.message||'',time=item.not_before_at&&item.status==='pending'?'после '+new Date(item.not_before_at).toLocaleString('ru-RU'):new Date(item.created_at).toLocaleString('ru-RU');return'<div class="log"><div class="log-meta"><span>'+esc(item.command+' · '+item.status)+'</span><span>'+esc(time)+'</span></div><div class="log-text">'+esc(message||'Ожидает результата')+'</div>'+(item.can_cancel?'<button class="btn command-cancel" data-id="'+item.id+'" style="margin-top:7px">Отменить</button>':'')+'</div>'}).join('')||'<div class="row-sub">Команд ещё не было.</div>');panel.innerHTML=stateHtml+commandHtml;panel.querySelectorAll('.command-cancel').forEa