function setAvatarPreview(url){const value=url||'/assets/xass-app-icon-192.png';$('siteAvatarPreview').src=value;$('siteAvatarEditPreview').src=value}
function updateProfilePreview(){const name=$('siteName').value.trim()||'XASS',title=$('siteTitle').value.trim()||'Публичный профиль';$('sitePreviewName').textContent=name;$('sitePreviewTitle').textContent=title;$('stackCount').textContent=$('siteStack').value.split(',').map(x=>x.trim()).filter(Boolean).length+' шт.';$('linksCount').textContent=$('siteLinks').value.split('\n').map(x=>x.trim()).filter(Boolean).length+' шт.'}
function setProfileDirty(dirty){state.profileDirty=dirty;$('profileSaveState').textContent=dirty?'Есть изменения':'Сохранено';$('profileSaveState').classList.toggle('changed',dirty);$('saveDockText').textContent=dirty?'Изменения ещё не сохранены':'Все изменения сохранены';try{dirty?tg?.enableClosingConfirmation?.():tg?.disableClosingConfirmation?.()}catch(e){}}
function markProfileDirty(){setProfileDirty(true);updateProfilePreview()}
const PROFILE_DRAFT_KEY='xass-profile-draft-v1';function readProfileDraft(){try{return JSON.parse(localStorage.getItem(PROFILE_DRAFT_KEY)||'null')}catch(e){return null}}function applyProfileDraft(draft){const p=draft?.profile||{},c=draft?.site_config||{};for(const [id,key] of [['siteName','name'],['siteUsername','username'],['siteTitle','title'],['siteBio','bio'],['siteTelegram','telegram_url'],['siteAvatar','avatar_url'],['siteQuote','quote']])if(key in p)$(id).value=p[key]||'';$('siteStack').value=(p.stack||[]).join(', ');$('siteLinks').value=(p.links||[]).map(x=>(x.label||'')+' | '+(x.url||'')).join('\n');if(/^#[0-9a-f]{6}$/i.test(c.accent_color||''))$('siteAccent').value=c.accent_color;const widgets=new Set(c.widgets||[]);document.querySelectorAll('[data-site-widget]').forEach(input=>input.checked=widgets.has(input.dataset.siteWidget));setAvatarPreview($('siteAvatar').value);markProfileDirty();toast('Черновик восстановлен')}
function renderSite(data){state.site=data;const p=data.profile||{},c=data.site_config||{},widgets=new Set(c.widgets||['about','quotes','music','weather','projects','contacts']);for(const [id,key] of [['siteName','name'],['siteUsername','username'],['siteTitle','title'],['siteBio','bio'],['siteTelegram','telegram_url'],['siteAvatar','avatar_url'],['siteQuote','quote']])$(id).value=p[key]||'';setAvatarPreview(p.avatar_url);$('siteStack').value=(p.stack||[]).join(', ');$('siteLinks').value=(p.links||[]).map(x=>(x.label||'')+' | '+(x.url||'')).join('\n');$('siteAccent').value=/^#[0-9a-f]{6}$/i.test(c.accent_color||'')?c.accent_color:'#376dff';document.querySelectorAll('[data-site-widget]').forEach(input=>input.checked=widgets.has(input.dataset.siteWidget));updateProfilePreview();setProfileDirty(false);renderProjects(data.projects||[]);loadQuotes();const url=data.public_url||location.origin+'/profile.php';$('homeOpenSite').href=url}
function loadSite(){api('site').then(r=>{if(!r.data?.ok)return toast(r.data?.detail||'Ошибка сайта');renderSite(r.data);if(state.draftPrompted)return;state.draftPrompted=true;const draft=readProfileDraft();if(draft?.profile)ask('На этом устройстве найден черновик профиля. Восстановить его?',ok=>ok&&applyProfileDraft(draft))})}
function profilePayload(){return{name:$('siteName').value,username:$('siteUsername').value,title:$('siteTitle').value,bio:$('siteBio').value,telegram_url:$('siteTelegram').value,avatar_url:$('siteAvatar').value,quote:$('siteQuote').value,stack:$('siteStack').value.split(',').map(x=>x.trim()).filter(Boolean),links:$('siteLinks').value.split('\n').map(line=>{const parts=line.split('|');return{label:(parts.shift()||'').trim(),url:parts.join('|').trim()}}).filter(x=>x.label&&x.url)}}
function siteConfigPayload(){return{accent_color:$('siteAccent').value,widgets:[...document.querySelectorAll('[data-site-widget]:checked')].map(input=>input.dataset.siteWidget)}}
$('saveProfileBtn').onclick=async function(){this.disabled=true;this.textContent='Сохраняю…';try{const [profileResult,configResult]=await Promise.all([api('site/profile',{method:'POST',body:profilePayload()}),api('site/config',{method:'POST',body:siteConfigPayload()})]);if(!profileResult.data?.ok)throw new Error(profileResult.data?.detail||'Профиль не сохранён');if(!configResult.data?.ok)throw new Error(configResult.data?.detail||'Стиль не сохранён');state.site={...state.site,profile:profileResult.data.profile,site_config:configResult.data.site_config};localStorage.removeItem(PROFILE_DRAFT_KEY);setProfileDirty(false);updateProfilePreview();toast('Изменения опубликованы');haptic('medium')}catch(e){toast(e.message||'Не удалось сохранить изменения')}finally{this.disabled=false;this.textContent='Сохранить изменения'}};$('saveProfileDraftBtn').onclick=()=>{try{localStorage.setItem(PROFILE_DRAFT_KEY,JSON.stringify({saved_at:new Date().toISOString(),profile:profilePayload(),site_config:siteConfigPayload()}));toast('Черновик сохранён только на этом устройстве')}catch(e){toast('Не удалось сохранить черновик')}};$('discardProfileBtn').onclick=()=>{if(!state.profileDirty)return toast('Несохранённых изменений нет');ask('Отменить несохранённые изменения профиля?',ok=>{if(!ok)return;localStorage.removeItem(PROFILE_DRAFT_KEY);renderSite(state.site);toast('Изменения отменены')})};$('openSiteBtn').onclick=()=>{const url=state.site?.public_url||location.origin+'/profile.php';tg?.openLink?tg.openLink(url):window.open(url,'_blank')};
['siteName','siteUsername','siteTitle','siteBio','siteTelegram','siteAvatar','siteStack','siteLinks','siteAccent'].forEach(id=>$(id).addEventListener('input',markProfileDirty));document.querySelectorAll('[data-site-widget]').forEach(input=>input.addEventListener('change',markProfileDirty));
$('siteAvatar').addEventListener('input',()=>setAvatarPreview($('siteAvatar').value.trim()));$('chooseAvatarBtn').onclick=()=>$('siteAvatarFile').click();$('clearAvatarBtn').onclick=()=>{$('siteAvatar').value='';setAvatarPreview('');markProfileDirty()};
function drawAvatarCrop(){const image=state.cropImage;if(!image)return;const canvas=$('avatarCropCanvas'),ctx=canvas.getContext('2d'),zoom=Number($('cropZoom').value)||1,base=Math.max(canvas.width/image.naturalWidth,canvas.height/image.naturalHeight),width=image.naturalWidth*base*zoom,height=image.naturalHeight*base*zoom,maxX=Math.max(0,(width-canvas.width)/2),maxY=Math.max(0,(height-canvas.height)/2),x=(canvas.width-width)/2+(Number($('cropX').value)||0)/100*maxX,y=(canvas.height-height)/2+(Number($('cropY').value)||0)/100*maxY;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,x,y,width,height)}
function closeAvatarCrop(){if(state.cropUrl)URL.revokeObjectURL(state.cropUrl);state.cropUrl='';state.cropImage=null;$('cropScreen').classList.remove('show');$('siteAvatarFile').value=''}
async function uploadCroppedAvatar(blob){$('chooseAvatarBtn').disabled=true;$('chooseAvatarBtn').textContent='Загружаю…';try{if(demo){$('siteAvatar').value='demo-avatar';setAvatarPreview(URL.createObjectURL(blob));toast('Демо: аватар кадрирован');return}const headers={'Content-Type':'image/jpeg'};if(initData)headers['X-Telegram-Init-Data']=initData;const response=await fetch('/proxy.php?_passthrough=1&_p='+encodeURIComponent('/api/mini/site/avatar'),{method:'POST',headers,body:blob,credentials:'include'}),data=await response.json();if(!response.ok||!data?.ok)throw new Error(data?.detail||'Ошибка загрузки');$('siteAvatar').value=data.avatar_url;setAvatarPreview(data.avatar_url);if(state.site)state.site.profile=data.profile;toast('Аватар обрезан и опубликован');haptic('medium')}catch(e){setAvatarPreview(state.site?.profile?.avatar_url||'');toast(e.message||'Не удалось загрузить аватар')}finally{$('chooseAvatarBtn').disabled=false;$('chooseAvatarBtn').textContent='Выбрать из галереи'}}
$('siteAvatarFile').addEventListener('change',()=>{const file=$('siteAvatarFile').files?.[0];if(!file)return;if(file.size>8*1024*1024){$('siteAvatarFile').value='';return toast('Файл больше 8 МБ')}if(!/^image\/(jpeg|png|webp)$/i.test(file.type)){ $('siteAvatarFile').value='';return toast('Нужен JPG, PNG или WebP')}state.cropUrl=URL.createObjectURL(file);const image=new Image();image.onload=()=>{state.cropImage=image;for(const id of ['cropZoom','cropX','cropY'])$(id).value=id==='cropZoom'?'1':'0';drawAvatarCrop();$('cropScreen').classList.add('show')};image.onerror=()=>{closeAvatarCrop();toast('Не удалось прочитать изображение')};image.src=state.cropUrl});for(const id of ['cropZoom','cropX','cropY'])$(id).addEventListener('input',drawAvatarCrop);$('cropCancel').onclick=closeAvatarCrop;$('cropApply').onclick=()=>{$('cropApply').disabled=true;$('avatarCropCanvas').toBlob(async blob=>{try{if(!blob)throw new Error('Не удалось обрезать изображение');closeAvatarCrop();await uploadCroppedAvatar(blob)}catch(e){toast(e.message)}finally{$('cropApply').disabled=false}},'image/jpeg',.9)};
function renderProjects(list){state.site=state.site||{};state.site.projects=list;$('projectList').innerHTML=list.map((p,index)=>'<div class="project"><div class="project-head"><div><div class="project-name">'+esc(p.title)+'</div><div class="project-desc">'+esc(p.description||p.subtitle||'Без описания')+'</div></div><span class="status">'+esc(p.status||'dev')+'</span></div><div class="device-actions"><button class="btn move-project" data-id="'+esc(p.id)+'" data-direction="up" aria-label="Поднять проект" '+(index===0?'disabled':'')+'>↑</button><button class="btn move-project" data-id="'+esc(p.id)+'" data-direction="down" aria-label="Опустить проект" '+(index===list.length-1?'disabled':'')+'>↓</button><button class="btn edit-project" data-id="'+esc(p.id)+'">Изменить</button><button class="btn danger delete-project" data-id="'+esc(p.id)+'">Удалить</button></div></div>').join('')||'<div class="empty">Проектов пока нет.</div>';document.querySelectorAll('.move-project').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const r=await api('site/projects/'+encodeURIComponent(b.dataset.id)+'/move',{method:'POST',body:{direction:b.dataset.direction}});if(!r.data?.ok)throw new Error(r.data?.detail||'Не удалось изменить порядок');renderProjects(r.data.projects||[])}catch(e){b.disabled=false;toast(e.message)}});document.querySelectorAll('.edit-project').forEach(b=>b.onclick=()=>openProject(list.find(p=>p.id===b.dataset.id)||{}));document.querySelectorAll('.delete-project').forEach(b=>b.onclick=()=>ask('Удалить проект?',ok=>ok&&api('site/projects/'+encodeURIComponent(b.dataset.id),{method:'DELETE'}).then(r=>r.data?.ok&&renderProjects(r.data.projects))))}
function openProject(p={}){const y=new Date().getFullYear();$('projectForm').style.display='block';$('projectFormTitle').textContent=p.id?'Редактировать проект':'Новый проект';$('projectId').value=p.id||'';$('projectTitle').value=p.title||'';$('projectStatus').value=p.status||'dev';$('projectSubtitle').value=p.subtitle||'';$('projectDescription').value=p.description||'';$('projectUrl').value=p.url||'';$('projectFrom').value=p.years?.from||y;$('projectTo').value=p.years?.to||y;$('projectTags').value=(p.tags||[]).join(', ');$('projectCover').value=p.cover?.src||'';$('projectCoverFile').value='';$('projectFeatured').checked=!!p.featured;$('projectForm').scrollIntoView({behavior:'smooth'})}function projectPayload(){return{id:$('projectId').value,title:$('projectTitle').value,status:$('projectStatus').value,subtitle:$('projectSubtitle').value,description:$('projectDescription').value,url:$('projectUrl').value,year_from:Number($('projectFrom').value),year_to:Number($('projectTo').value),tags:$('projectTags').value.split(',').map(x=>x.trim()).filter(Boolean),cover_type:'image',cover_src:$('projectCover').value,featured:$('projectFeatured').checked}}async function uploadProjectCover(projectId,file){if(file.size>10*1024*1024)throw new Error('Обложка больше 10 МБ');if(!/^image\/(jpeg|png|webp)$/i.test(file.type))throw new Error('Нужен JPG, PNG или WebP');const headers={'Content-Type':file.type};if(initData)headers['X-Telegram-Init-Data']=initData;const response=await fetch('/proxy.php?_passthrough=1&_p='+encodeURIComponent('/api/mini/site/projects/'+projectId+'/cover'),{method:'POST',headers,body:file,credentials:'include'}),data=await response.json().catch(()=>({}));if(!response.ok||!data?.ok)throw new Error(data?.detail||'Не удалось загрузить обложку');return data}$('newProjectBtn').onclick=()=>openProject();$('cancelProjectBtn').onclick=()=>{$('projectForm').style.display='none'};$('saveProjectBtn').onclick=async function(){if(!$('projectTitle').value.trim())return toast('Введите название');const file=$('projectCoverFile').files?.[0];this.disabled=true;this.textContent='Сохраняю…';try{let r=await api('site/projects',{method:'POST',body:projectPayload()});if(!r.data?.ok)throw new Error(r.data?.detail||'Проект не сохранён');if(file){r={data:await uploadProjectCover(r.data.project.id,file)};$('projectCover').value=r.data.cover_url}renderProjects(r.data.projects||[]);$('projectForm').style.display='none';toast(file?'Проект и обложка сохранены':'Проект сохранён')}catch(e){toast(e.message||'Ошибка сохранения')}finally{this.disabled=false;this.textContent='Сохранить'}};
async function loadDiagnostics(copy=false){try{const r=await api('diagnostics');if(!r.data?.ok)throw new Error(r.data?.detail||'Диагностика недоступна');const d=r.data,text=['Backend XASS '+d.app_version,'База: '+d.database.status,'Сайт: '+d.connection.status+(d.connection.latency_ms!=null?' · '+d.connection.latency_ms+' мс':''),'Telegram: '+d.telegram.mode+' · '+(d.telegram.configured?'настроен':'не настроен'),'Архив: '+d.archive.targets+' хранилищ · '+d.archive.media+' медиа','Диск: '+valueText(d.storage.disk_used_percent,'%')+' · свободно '+valueText(d.storage.disk_free_gb,' ГБ'),'Обновления: '+(d.updates.has_updates?'доступны':'актуально'),'Конфигурация: '+(d.configuration.ok?'OK':d.configuration.issues.join('; '))].join('\n');$('diagnosticResult').textContent=text;if(copy)await copyText(JSON.stringify(d,null,2));if(copy)toast('Безопасный отчёт скопирован')}catch(e){$('diagnosticResult').textContent=e.message||'Ошибка диагностики';toast(e.message)}}$('copyDiag').onclick=()=>loadDiagnostics(true);document.querySelectorAll('[data-diag-action]').forEach(btn=>btn.onclick=()=>{const action=btn.dataset.diagAction,run=async()=>{btn.disabled=true;try{if(action==='test-notification'){const r=await api('diagnostics/test-notification',{method:'POST'});if(!r.data?.ok)throw new Error(r.data?.detail||'Тест не выполнен');toast('Тестовое уведомление создано');loadNotifications();return}const dangerous=['restart_backend','rollback_update'].includes(action),proof=dangerous?await passkeyAction('diagnostics:'+action):'',source=(state.boot?.sources||[]).find(x=>x.is_online)?.source_name||'',r=await api('diagnostics/action',{method:'POST',headers:{'X-XASS-Action-Proof':proof},body:{action,source_name:source}});if(!r.data?.ok)throw new Error(r.data?.detail||'Действие не выполнено');toast(r.data.message||'Готово');loadDiagnostics()}catch(e){if(e?.name!=='NotAllowedError')toast(e.message)}finally{btn.disabled=false}};['restart_backend','rollback_update'].includes(action)?ask('Выполнить опасное действие восстановления?',ok=>ok&&run()):run()});
$('logoutBtn').onclick=()=>pwaApi('logout',{method:'POST'}).then(()=>location.reload());
$('logoutAllBtn').onclick=()=>ask('Завершить все standalone-сеансы XASS? На каждом устройстве потребуется новый вход.',async ok=>{if(!ok)return;try{const proof=await passkeyAction('sessions:logout-all'),r=await pwaApi('logout-all',{method:'POST',headers:{'X-XASS-Action-Proof':proof}});if(!r.data?.ok)throw new Error(r.data?.detail||'Не удалось завершить сеансы');location.reload()}catch(e){if(e?.name!=='NotAllowedError')toast(e.message)}});
