function loginReadiness(config={}){const req=config.requirements||{},labels={bot_token:'BOT_TOKEN найден',bot_username:'Бот определён',owner_user_id:'OWNER_USER_ID настроен',https:'HTTPS доступен'},rows=Object.keys(labels).map(key=>'<div class="ready-row '+(req[key]?'ok':'bad')+'"><span class="ready-icon">'+(req[key]?'✓':'!')+'</span><span>'+labels[key]+'</span></div>').join('');return'<div class="login-readiness"><h3>Локальная готовность XASS</h3><p>Это отдельная проверка сервера. Состояние /setdomain может подтвердить только Telegram.</p>'+rows+'</div>'}
async function initPwa(){$('deny').style.display='none';$('login').style.display='none';$('loader').style.display='flex';try{const pairToken=new URLSearchParams(location.hash.replace(/^#/,''));const token=pairToken.get('pair')||'';if(token){const exchange=await pwaApi('exchange',{method:'POST',body:{token}});if(exchange.status!==200||!exchange.data?.ok)throw new Error(exchange.data?.detail||'Одноразовая ссылка недействительна');history.replaceState(null,'',location.pathname+location.search);return loadBoot()}const r=await pwaApi('config');if(r.status!==200||!r.data?.ok)throw new Error(r.data?.detail||'Не удалось проверить вход');const config=r.data;state.pwaConfig=config;if(config.authenticated)return loadBoot();$('loader').style.display='none';$('login').style.display='block';$('telegramWidget').replaceChildren();$('passkeyLoginBtn').style.display=config.passkey_available?'block':'none';$('passkeyLoginBtn').onclick=async()=>{const button=$('passkeyLoginBtn');button.disabled=true;try{await passkeyAuthenticate('login');$('login').style.display='none';$('loader').style.display='flex';await loadBoot()}catch(e){toast(passkeyErrorMessage(e))}finally{button.disabled=false}};if(!config.login_ready){$('telegramWidget').innerHTML=loginReadiness(config)+'<div class="ios-help">Откройте свежую одноразовую ссылку, созданную внутри Telegram Mini App — для неё BotFather не нужен.</div>';return}window.onTelegramAuth=async user=>{try{const login=await pwaApi('login',{method:'POST',body:user});if(login.status!==200||!login.data?.ok)throw new Error(login.data?.detail||'Вход отклонён');$('login').style.display='none';$('loader').style.display='flex';await loadBoot()}catch(e){toast(e.message)}};const script=document.createElement('script');script.async=true;script.src='https://telegram.org/js/telegram-widget.js?22';script.dataset.telegramLogin=config.bot_username;script.dataset.size='large';script.dataset.userpic='false';script.dataset.radius='12';script.dataset.onauth='onTelegramAuth(user)';script.onerror=()=>{$('telegramWidget').innerHTML='<div class="login-readiness"><h3>Виджет Telegram не загрузился</h3><p>Вернитесь в Telegram Mini App и создайте одноразовую ссылку для iPhone. Она работает без Login Widget и проверки /setdomain.</p></div>'};$('telegramWidget').appendChild(script)}catch(e){showDeny(e.message||'Не удалось войти')}}
function updateOnlineState(){if(!$('app').hidden){$('headStatus').textContent=navigator.onLine?'Проверка связи…':'Нет интернета';$('headDot').className='dot'}}window.addEventListener('online',()=>{updateOnlineState();if(!$('app').hidden||initData)loadBoot();else initPwa()});window.addEventListener('offline',()=>{updateOnlineState();toast('Нет интернета — данные на экране могли устареть')});
function setupServiceWorker(){
  if(!('serviceWorker'in navigator)||(typeof demo!=='undefined'&&demo))return;
  const wasControlled=!!navigator.serviceWorker.controller;
  const reloadButton=document.createElement('button');
  reloadButton.id='reloadPwaBtn';reloadButton.className='btn blue';reloadButton.textContent='Обновить приложение';reloadButton.hidden=true;
  $('installPwaBtn').after(reloadButton);
  reloadButton.onclick=()=>{
    if(state.profileDirty)ask('Есть несохранённые изменения. Обновить страницу?',ok=>ok&&location.reload());
    else location.reload();
  };
  navigator.serviceWorker.addEventListener('message',event=>{
    if(event.data?.type!=='XASS_SW_UPDATED'||!wasControlled)return;
    // Never interrupt a one-time login, Passkey prompt or unsaved form.
    reloadButton.hidden=false;
    toast('Новая версия готова. Нажмите «Обновить приложение» в разделе iPhone.');
  });
  navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'}).then(registration=>{
    const check=()=>registration.update().catch(error=>console.warn('XASS service worker update failed',error));
    check();setInterval(check,60*60*1000);
  }).catch(error=>{console.warn('XASS service worker registration failed',error);toast('Offline-режим пока недоступен')});
}
setupServiceWorker();
